# Frontend Cloudflare Deployment

This service deploys the Nucleum, Memotron, and Pointron static frontend builds
to Cloudflare Workers Static Assets.

The existing AWS/CDK `turbo-deploy.yml` workflow is intentionally left in place.
Cloudflare frontend deploys use separate workflows and scripts.

## Domains

Frontend routes:

- Dev: `dev.<product-domain>`
- Pre: `pre.<product-domain>`
- Live: `web.<product-domain>`

Current products:

- `nucleum` -> `nucleum.app`
- `memotron` -> `memotron.app`
- `pointron` -> `pointron.app`

The app resolves the account service from the frontend origin, for example:

- `dev.memotron.app` -> `account-{region}-dev.memotron.app`
- `pre.pointron.app` -> `account-{region}-pre.pointron.app`
- `web.nucleum.app` -> `account-{region}.nucleum.app`

## Code Deploy

Code/assets deploys do not modify routes.

```sh
npm --workspace @21n/frontend-deploy run deploy:dev -- --products=all
npm --workspace @21n/frontend-deploy run deploy:pre -- --products=nucleum
npm --workspace @21n/frontend-deploy run deploy:live -- --products=memotron,pointron
```

Use `--dry-run` to validate the generated Wrangler config without publishing.
Use `--skip-build` only when `apps/<app>/build/index.html` already exists.

## Route Sync

Routes are synced separately, like the account service. This is intentionally
not part of continuous deploy.

```sh
npm --workspace @21n/frontend-deploy run routes:dev -- --products=all
npm --workspace @21n/frontend-deploy run routes:pre -- --products=all
npm --workspace @21n/frontend-deploy run routes:live -- --products=all
```

The route script preflights all requested Cloudflare zones before creating or
updating routes. If `memotron.app` or `pointron.app` is not visible to the API
token, the run fails before mutating any zone.

Required token permissions:

- Account Workers Scripts edit
- Zone read for each product zone
- Workers routes edit for each product zone

Optional zone ID overrides:

- `CLOUDFLARE_ZONE_ID_NUCLEUM_APP`
- `CLOUDFLARE_ZONE_ID_MEMOTRON_APP`
- `CLOUDFLARE_ZONE_ID_POINTRON_APP`

## WAF Exceptions

The product frontend hosts serve static Worker assets and the SvelteKit app
shell. Cloudflare managed WAF can false-positive on normal `GET`/`HEAD`
navigation and asset requests with OWASP rule `949110: Inbound Anomaly Score
Exceeded`. Sync a host-scoped managed-rules exception for the selected
product/environment:

```sh
npm --workspace @21n/frontend-deploy run waf:dev -- --products=nucleum
npm --workspace @21n/frontend-deploy run waf:pre -- --products=all
npm --workspace @21n/frontend-deploy run waf:live -- --products=all
```

The exception skips only the anomaly block rule configured in
`config/environments.json`; other WAF rules and non-frontend hosts remain
unchanged. Use `--dry-run` to print the rule without Cloudflare credentials.
Remote sync requires a token with zone read and zone WAF write access. The token
can be provided as `CLOUDFLARE_WAF_TOKEN`, or via the same fallback variables
used by route sync.

## GitHub Workflows

- `frontend-cloudflare-deploy.yml`
  - Push to `dev`: deploys all products to `dev`
  - `frontend-pre-*` tag: deploys all products to `pre`
  - `frontend-live-*` tag: deploys all products to `live`
  - Manual dispatch: deploy one product or all products

- `frontend-cloudflare-routes.yml`
  - Manual only
  - Syncs Worker routes for selected environment/products
import fs from 'node:fs';
import path from 'node:path';

export function readConfig(serviceRoot) {
  return JSON.parse(fs.readFileSync(path.join(serviceRoot, 'config/environments.json'), 'utf8'));
}

export function normalizeEnvironment(value) {
  const normalized = String(value ?? '').trim().toLowerCase();
  if (['dev', 'pre', 'live'].includes(normalized)) return normalized;
  return null;
}

export function readEnvironment(config, environment) {
  const envConfig = config.environments[environment];
  if (!envConfig) {
    throw new Error(`Unknown frontend environment: ${environment}`);
  }
  return envConfig;
}

export function parseProducts(config, value) {
  const known = Object.keys(config.products);
  if (!value || value === 'all') return known;
  const products = value.split(',').map((entry) => entry.trim()).filter(Boolean);
  for (const product of products) {
    if (!config.products[product]) {
      throw new Error(`Unknown frontend product: ${product}. Expected one of: ${known.join(', ')}`);
    }
  }
  return Array.from(new Set(products));
}

export function getArgValue(argv, name) {
  const prefix = `--${name}=`;
  const inline = argv.find((arg) => arg.startsWith(prefix));
  if (inline) return inline.slice(prefix.length);

  const index = argv.indexOf(`--${name}`);
  if (index >= 0) return argv[index + 1];
  return undefined;
}

export function hasFlag(argv, name) {
  return argv.includes(`--${name}`);
}

export function workerName(config, environment, productId) {
  return `${config.workerNamePrefix}-${productId}-${environment}`;
}

export function webHost(config, environment, productId) {
  const envConfig = readEnvironment(config, environment);
  const product = config.products[productId];
  return `${envConfig.webSubdomain}.${product.domain}`;
}

export function buildEnv(config, environment, productId) {
  const envConfig = readEnvironment(config, environment);
  const product = config.products[productId];
  if (!product) {
    throw new Error(`Unknown frontend product: ${productId}`);
  }

  const accountBaseUrlTemplate = envConfig.accountBaseUrlTemplate?.replaceAll('{domain}', product.domain);
  return removeUndefinedValues({
    ...config.defaultBuildEnv,
    ...envConfig.buildEnv,
    ...product.env?.[environment],
    VITE_PRODUCT: product.viteProduct ?? productId,
    VITE_HOST: webHost(config, environment, productId),
    VITE_ACCOUNT_BASE_URL_TEMPLATE: accountBaseUrlTemplate
  });
}

export function routeDefinitions(config, environment, products = Object.keys(config.products)) {
  readEnvironment(config, environment);
  return products.map((productId) => ({
    pattern: `${webHost(config, environment, productId)}/*`,
    script: workerName(config, environment, productId),
    zoneName: config.products[productId].domain
  }));
}

export function wafExceptionDefinitions(config, environment, products = Object.keys(config.products)) {
  readEnvironment(config, environment);
  const staticFrontend = config.waf?.staticFrontend;
  if (!staticFrontend?.rules) {
    throw new Error('Missing static frontend WAF exception config.');
  }

  return products.map((productId) => {
    const host = webHost(config, environment, productId);
    return {
      zoneName: config.products[productId].domain,
      rule: {
        ref: `21n_frontend_worker_asset_${environment}_${productId}`,
        description: `21n static frontend WAF exception: ${environment}/${productId}`,
        expression: [
          `http.host eq ${quoteCloudflareString(host)}`,
          `http.request.method in ${cloudflareStringSet(staticFrontend.methods ?? ['GET'])}`
        ].join(' and '),
        action: 'skip',
        action_parameters: {
          rules: staticFrontend.rules
        },
        logging: {
          enabled: true
        },
        enabled: true
      }
    };
  });
}

export function renderWranglerConfig(serviceRoot, repoRoot, config, environment, productId) {
  const envConfig = readEnvironment(config, environment);
  const product = config.products[productId];
  if (!product) {
    throw new Error(`Unknown frontend product: ${productId}`);
  }

  const outputDir = path.join(serviceRoot, '.wrangler');
  fs.mkdirSync(outputDir, { recursive: true });

  const buildDir = path.join(repoRoot, product.appPath, 'build');
  const wranglerConfig = {
    $schema: toPosixPath(path.relative(outputDir, path.join(repoRoot, 'node_modules/wrangler/config-schema.json'))),
    name: workerName(config, environment, productId),
    compatibility_date: config.compatibilityDate ?? '2026-05-16',
    workers_dev: envConfig.workersDev === true,
    assets: {
      directory: toPosixPath(path.relative(outputDir, buildDir)),
      not_found_handling: 'single-page-application'
    },
    observability: {
      enabled: true
    }
  };

  const outputPath = path.join(outputDir, `wrangler.${environment}.${productId}.deploy.jsonc`);
  fs.writeFileSync(outputPath, `${JSON.stringify(wranglerConfig, null, 2)}\n`);
  return outputPath;
}

export function writeCloudflareAssetHeaders(repoRoot, config, productId) {
  const product = config.products[productId];
  if (!product) {
    throw new Error(`Unknown frontend product: ${productId}`);
  }
"}

